from pathlib import Path
import subprocess, sys
root = Path('12-AZ-IP')
selected = {'01','03','04','11','12','14','15','19','20','21','22','23', *map(str, range(28, 44))}
pruned = {'.venv','node_modules','build','dist','.gradle','__pycache__'}
roots = []
for product in sorted(root.iterdir()):
    if not product.is_dir() or product.name[:2] not in selected:
        continue
    for tests in product.rglob('tests'):
        if any(part in pruned for part in tests.parts):
            continue
        if any(tests.rglob('test_*.py')):
            roots.append(tests)
failures = []
for tests in roots:
    print(f'=== {tests} ===', flush=True)
    result = subprocess.run([sys.executable, '-m', 'pytest', str(tests), '-q'], text=True, capture_output=True)
    tail = (result.stdout + result.stderr).strip().splitlines()
    summary = next((line for line in reversed(tail) if ' passed' in line or ' failed' in line or ' error' in line or ' no tests' in line), 'no pytest summary')
    print(summary, flush=True)
    if result.returncode:
        failures.append((str(tests), result.returncode, result.stdout, result.stderr))
if failures:
    print(f'FAILED SUITES: {len(failures)} / {len(roots)}', flush=True)
    for path, code, stdout, stderr in failures:
        print(f'--- {path} (exit {code}) ---\n{stdout}\n{stderr}', flush=True)
    raise SystemExit(1)
print(f'ALL {len(roots)} PRODUCT PYTEST ROOTS PASSED', flush=True)
